import 'package:fluffle/core/config/app_config_provider.dart';
import 'package:fluffle/l10n/generated/app_localizations.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:material_ui/material_ui.dart';

/// Root widget of the app.
class const App({super.key}) extends ConsumerWidget {

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    return MaterialApp(
      onGenerateTitle: (context) => L10n.of(context).appTitle,
      // Listed by hand on purpose: the delegates generated by gen-l10n still
      // point at flutter_localizations and crash with material_ui
      // (flutter/flutter#191072). Revisit when that issue is fixed.
      localizationsDelegates: const [
        L10n.delegate,
        ...GlobalMaterialLocalizations.delegates,
      ],
      supportedLocales: L10n.supportedLocales,
      home: const _FoundationPlaceholder(),
    );
  }
}

/// Temporary home screen until the router is in place.
class const _FoundationPlaceholder() extends ConsumerWidget {

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final l10n = L10n.of(context);
    final flavor = ref.watch(appConfigProvider).flavor;
    return Scaffold(
      body: Center(
        child: Column(
          mainAxisSize: .min,
          children: [
            Text(l10n.foundationReady),
            Text(l10n.flavorLabel(flavor.name)),
          ],
        ),
      ),
    );
  }
}
